const make=(id,chapter,row)=>{const [prompt,answer,explanation]=row;const p=Array.isArray(answer)?{id:'a',type:'choice',label:'Выберите верное утверждение',options:answer.map((text,i)=>({id:String(i),text})),answer:'0'}:{id:'a',type:'number',label:'Введите число или дробь',answer};return {id,chapter,title:Array.isArray(answer)?'Проверка условий':'Вычисление',prompt,parts:[p],hint:explanation,explanation};};
export const YEAR_TWO_PRACTICE=groups.flatMap(([chapter,rows],g)=>rows.map((r,i)=>make('l'+(16+g)+'-'+(i+1),chapter,r)));
export const YEAR_TWO_TEST=groups.flatMap(([chapter,,rows],g)=>rows.map((r,i)=>make('t-'+(76+g*5+i),chapter,r)));
